// Works series, managed by the client in the CMS (src/data/series.json is generated by
// scripts/fetch-cms.mjs). Used for the works filter buttons and "About the series".
import seriesData from "../data/series.json";
import works from "../data/works.json";

type Lang = "en" | "es";

export interface Series {
	key: string;
	name: Record<Lang, string>;
	description: Record<Lang, string> | null;
}

const all = seriesData as Series[];
const used = new Set((works as { series?: string }[]).map((w) => w.series).filter(Boolean));

/** Series that have at least one published work, in the client's CMS order. */
export function seriesWithWorks(): Series[] {
	return all.filter((s) => used.has(s.key));
}

/** Display name of a series key, falling back to the key itself. */
export function seriesName(key: string | undefined, lang: Lang): string {
	if (!key) return "";
	return all.find((s) => s.key === key)?.name[lang] ?? key;
}
